INSERT INTO `course_lessons` VALUES (1,1,1,'Buổi 1: Giới thiệu HTML5, Cấu trúc trang Web & Công cụ lập trình (Git/VSCode)','Nắm vững cú pháp HTML5 semantic (header, nav, main, section, footer), thiết lập môi trường Git repository nhóm, cấu trúc thư mục dự án và làm quen với quy trình cộng tác mã nguồn.','Xây dựng trang CV / Profile cá nhân bằng HTML5 chuẩn semantic, nạp lên kho lưu trữ GitHub và đính kèm tệp nén mã nguồn (.zip) hoặc link repository.',NULL,NULL,'2026-11-01 12:03:00','2026-10-31 12:42:00'),(2,1,2,'Buổi 2: Thiết kế giao diện CSS3 nâng cao, Flexbox, Grid & Framework Tailwind CSS','Áp dụng Flexbox, CSS Grid và hệ sinh thái Tailwind CSS để thiết kế giao diện đáp ứng (Responsive Design) tương thích mọi kích thước màn hình PC/Tablet/Mobile.','Thiết kế giao diện hoàn chỉnh gồm thanh điều hướng Navbar cố định, Banner chính, danh sách thẻ Grid sản phẩm/dịch vụ và chân trang Footer chuẩn UX/UI.',NULL,NULL,'2026-10-24 12:33:00','2026-10-31 12:42:00'),(3,1,3,'Buổi 3: Lập trình PHP căn bản, Cú pháp, Xử lý mảng & Biểu mẫu Form GET/POST','Cú pháp PHP 8, mảng kết hợp (Associative Array), kỹ thuật tách mã `require_once`, xử lý nhận dữ liệu biểu mẫu `$_GET` và `$_POST`, lọc và làm sạch dữ liệu đầu vào.','Xây dựng biểu mẫu Form tiếp nhận thông tin yêu cầu hỗ trợ, kiểm tra tính hợp lệ dữ liệu (Validate server-side) và hiển thị kết quả hoặc thông báo lỗi trực quan.',NULL,NULL,'2026-09-26 23:59:00','2026-10-31 12:42:00'),(4,1,4,'Buổi 4: Kết nối CSDL MySQL bằng PDO & Prepared Statement chống SQL Injection','Kết nối cơ sở dữ liệu qua lớp PDO, cấu hình thuộc tính bắt lỗi PDOException, cơ chế Prepared Statement bảo mật chống lại các cuộc tấn công SQL Injection nguy hiểm.','Tạo cơ sở dữ liệu `helpdesk_thudo`, viết file `database.php` khởi tạo kết nối PDO tập trung, thực thi câu lệnh truy vấn có tham số `:param` an toàn tuyệt đối.',NULL,NULL,'2026-11-24 12:59:00','2026-10-31 12:42:00'),(5,1,5,'Buổi 5: Xây dựng hệ thống chức năng CRUD hoàn chỉnh theo quy chuẩn ITIL Service Desk','Xây dựng đầy đủ 4 thao tác dữ liệu cốt lõi: Create, Read (kèm tìm kiếm & phân trang), Update, Delete (bảo vệ bằng phương thức POST và mẫu thiết kế Post-Redirect-Get).','Hoàn thiện module CRUD quản lý người dùng / quản lý phiếu hỗ trợ, đảm bảo không xóa dữ liệu bằng link GET, có Flash message phản hồi sau thao tác.',NULL,NULL,'2026-10-10 23:59:00','2026-10-31 12:42:00'),(6,1,6,'Buổi 6: Kiến trúc hướng đối tượng OOP, Composer, PSR-4 Autoloading & Mô hình MVC chuẩn','Áp dụng lập trình hướng đối tượng OOP (Class, Object, Constructor, Dependency Injection), định tuyến qua Front Controller, bóc tách 3 tầng Model/Repository, View, Controller.','Tái cấu trúc (Refactor) module nghiệp vụ sang MVC: Front Controller tiếp nhận request, Controller điều hướng, Model truy vấn CSDL, View chỉ hiển thị giao diện.',NULL,NULL,'2026-10-17 23:59:00','2026-10-31 12:42:00'),(7,1,7,'Buổi 7: Xác thực (Authentication), Phân quyền (RBAC), Quản lý Session & Bảo mật CSRF','Bảo mật mật khẩu một chiều với thuật toán Bcrypt (`password_hash` & `password_verify`), Guard phân quyền ở server theo vai trò người dùng, kiểm tra quyền sở hữu Ownership và Token chống giả mạo CSRF.','Tích hợp đăng nhập an toàn, cơ chế Guard chặn người dùng truy cập trái phép, thêm thẻ ẩn `<input type=\\\"hidden\\\" name=\\\"csrf\\\">` cho toàn bộ form thay đổi dữ liệu.',NULL,NULL,'2026-10-24 23:59:00','2026-10-31 12:42:00'),(8,1,8,'Buổi 8: Lập trình không đồng bộ Fetch API, JSON Endpoint & Cập nhật DOM an toàn','Xây dựng Web API trả dữ liệu chuẩn JSON (`application/json`), sử dụng JavaScript Fetch API với cú pháp async/await, cập nhật giao diện không tải lại trang, phòng chống XSS bằng textContent.','Tạo Endpoint JSON tìm kiếm dữ liệu, viết hàm Fetch JavaScript gọi API kèm debounce 300ms, hiển thị trạng thái loading / empty / error và render dữ liệu an toàn.',NULL,NULL,'2026-11-01 18:11:00','2026-10-31 12:42:00'),(9,1,9,'Buổi 9: Báo cáo bảo vệ Bài tập lớn, Demo luồng nghiệp vụ & Vấn đáp kỹ thuật','Tổng duyệt bản phát hành Release Candidate, kiểm tra toàn bộ luồng chức năng phân hệ, chạy test case kiểm thử CSDL, bảo mật, API và chuẩn bị slide kịch bản demo 20 phút trước hội đồng.','Đóng gói toàn bộ sản phẩm hoàn chỉnh, cập nhật tài liệu README, bảng tài khoản thử nghiệm và kịch bản thuyết trình bảo vệ đồ án của nhóm.',NULL,NULL,'2026-11-01 23:38:00','2026-10-31 12:42:00'),(10,3,1,'Buổi 1: Mô hình Thực thể Quan hệ (ERD) & Phân tích yêu cầu bài toán','Thiết kế ERD chuẩn hóa cho hệ thống quản lý dữ liệu.','Nộp file báo cáo thực hành (.pdf) hoặc kịch bản lệnh SQL (.sql) có chú thích chi tiết.',NULL,NULL,'2026-09-15 23:59:00','2026-10-31 12:42:00'),(11,3,2,'Buổi 2: Chuẩn hóa dữ liệu (1NF, 2NF, 3NF, BCNF) & Toàn vẹn tham chiếu','Phân tích loại bỏ dị thường thêm/xóa/sửa trong lược đồ quan hệ.','Nộp file báo cáo thực hành (.pdf) hoặc kịch bản lệnh SQL (.sql) có chú thích chi tiết.',NULL,NULL,'2026-09-22 23:59:00','2026-10-31 12:42:00'),(12,3,3,'Buổi 3: Ngôn ngữ định nghĩa dữ liệu DDL (CREATE, ALTER, DROP, CONSTRAINT)','Tạo bảng, chỉ mục và thiết lập các khóa ngoại FOREIGN KEY an toàn.','Nộp file báo cáo thực hành (.pdf) hoặc kịch bản lệnh SQL (.sql) có chú thích chi tiết.',NULL,NULL,'2026-09-29 23:59:00','2026-10-31 12:42:00'),(13,3,4,'Buổi 4: Ngôn ngữ thao tác dữ liệu DML nâng cao (JOIN, GROUP BY, HAVING)','Viết các câu truy vấn thống kê dữ liệu đa bảng phức tạp.','Nộp file báo cáo thực hành (.pdf) hoặc kịch bản lệnh SQL (.sql) có chú thích chi tiết.',NULL,NULL,'2026-10-06 23:59:00','2026-10-31 12:42:00'),(14,3,5,'Buổi 5: View, Stored Procedure & User Defined Function','Lập trình thủ tục lưu trữ trên máy chủ CSDL MySQL.','Nộp file báo cáo thực hành (.pdf) hoặc kịch bản lệnh SQL (.sql) có chú thích chi tiết.',NULL,NULL,'2026-10-13 23:59:00','2026-10-31 12:42:00'),(15,3,6,'Buổi 6: Trigger kiểm soát toàn vẹn dữ liệu & Transaction ACID','Thiết lập Trigger tự động lưu nhật ký và kiểm soát giao dịch an toàn.','Nộp file báo cáo thực hành (.pdf) hoặc kịch bản lệnh SQL (.sql) có chú thích chi tiết.',NULL,NULL,'2026-10-20 23:59:00','2026-10-31 12:42:00'),(16,3,7,'Buổi 7: Tối ưu hóa truy vấn, Indexing B-Tree & Quản lý phân quyền người dùng CSDL','Phân tích câu lệnh bằng EXPLAIN, đánh chỉ mục tối ưu thời gian phản hồi.','Nộp file báo cáo thực hành (.pdf) hoặc kịch bản lệnh SQL (.sql) có chú thích chi tiết.',NULL,NULL,'2026-10-27 23:59:00','2026-10-31 12:42:00'),(17,3,8,'Buổi 8: Sao lưu, Phục hồi dữ liệu (Backup & Disaster Recovery) & Nghiệm thu CSDL','Thực hành sao lưu mysqldump và lập phương án khôi phục sự cố dữ liệu.','Nộp file báo cáo thực hành (.pdf) hoặc kịch bản lệnh SQL (.sql) có chú thích chi tiết.',NULL,NULL,'2026-11-03 23:59:00','2026-10-31 12:42:00'),(19,1,3,'Xây dựng minishop theo CRUD','Xây dựng minishop theo CRUD','Đẩy link cá nhân và link nhóm',NULL,NULL,'2026-10-07 23:47:00','2026-11-01 23:47:17'),(20,1,10,'Bài tập cuốikyf','Nộp bản báo cáo','Nộp cả file pdf, của nhóm và cá nhân',NULL,NULL,'2026-11-02 12:00:00','2026-11-02 08:44:23');
