INSERT INTO `ticket_replies` VALUES (1,3,2,'Chào bạn Linh, KTV đã nhận được ảnh thẻ sinh viên TUD D24 của bạn và đang đối chiếu với CSDL Đào tạo.',NULL,0,'2026-10-23 08:40:00'),(2,3,2,'Ghi chú nội bộ: Đã đối chiếu CCCD khớp hồ sơ tuyển sinh D24. Sẽ cấp pass tạm 123456 và gửi về tranlinh.personal@gmail.com.',NULL,1,'2026-10-23 08:42:00'),(3,4,4,'KTV đã kiểm tra văn bản phê duyệt của P.ĐT và mở quyền nộp điểm cho thầy đến hết 17h00 ngày 23/10.',NULL,0,'2026-10-22 14:25:00'),(4,5,6,'KTV đã giải phóng lease IP tại tầng 3 KTX Nhà B. Bạn quên mạng cũ và kết nối lại theo chuẩn PEAP/MSCHAPv2 nhé.',NULL,0,'2026-10-21 11:30:00'),(5,3,14,'oke ạ',NULL,0,'2026-10-29 08:51:13'),(6,3,2,'KTV gửi ảnh minh chứng đã cấu hình thành công mở khóa trên hệ thống.','uploads/replies/reply_3_test_1793239303.png',0,'2026-10-29 09:01:43'),(7,3,2,'KTV gửi ảnh minh chứng đã cấu hình thành công mở khóa trên hệ thống.','uploads/replies/reply_3_test_1793239324.png',0,'2026-10-29 09:02:04'),(8,3,2,'ddggg',NULL,0,'2026-10-29 09:04:19'),(9,3,14,'ggasaagsfsgffggg',NULL,0,'2026-10-29 09:04:45'),(10,1,5,'đã chỉnh sửa lại ngày',NULL,0,'2026-10-29 09:15:28'),(11,1,1,'đã giải quyết',NULL,0,'2026-10-29 09:17:36'),(12,7,2,'✅ [BIÊN BẢN NGHIỆM THU GIẢI PHÁP KỸ THUẬT]:\nsfasff',NULL,0,'2026-10-29 09:23:10'),(13,3,5,'KTV đã cấu hình xong tài khoản Canvas LMS cho bạn, hệ thống hoạt động bình thường.',NULL,0,'2026-10-29 09:38:02'),(14,3,5,'Xác nhận đóng hoàn tất phiếu yêu cầu hỗ trợ.',NULL,0,'2026-10-29 09:38:02'),(15,2,5,'Test giai phap ky thuat',NULL,0,'2026-10-29 09:41:30'),(16,6,5,'Hoan tat dong phieu',NULL,0,'2026-10-29 09:42:21'),(17,9,2,'Kỹ thuật viên đã xử lý và cung cấp giải pháp khắc phục sự cố.',NULL,0,'2026-10-29 09:44:58'),(18,8,6,'Kỹ thuật viên đã hoàn tất hỗ trợ và đóng phiếu thành công.',NULL,0,'2026-10-29 09:45:12'),(19,7,2,'Đã khắc phục xong sự cố xác thực tài khoản SSO thành công.',NULL,0,'2026-10-29 16:16:44'),(20,7,2,'Đã hoàn tất hỗ trợ và đóng phiếu thành công.',NULL,0,'2026-10-29 16:16:55'),(2