INSERT INTO `tickets` VALUES (1,1,5,4,1,NULL,1,6,NULL,0,NULL,NULL,'[SỰ CỐ DIỆN RỘNG] Hiệu chỉnh lịch học trùng ngày nghỉ lễ trên Canvas LMS','KTV cấu hình sinh lịch học tự động đầu kỳ chưa trừ ngày nghỉ lễ 30/4 - 1/5 và 2/9. Cần chạy script CLI đồng bộ lại toàn trường.','Canvas LMS',NULL,'resolved','completed','2026-10-23 08:00:00','2026-10-23 08:00:00','2026-10-23 08:15:00','2026-10-23 10:00:00','2026-10-23 08:10:00','2026-10-29 09:17:36','2026-10-29 09:17:48',0,'HD-2026-2910-T0L001',0,0,NULL,0,NULL,NULL,'pending',NULL,NULL,0,NULL,NULL,0,NULL,'none'),(2,13,5,4,2,1,1,1,NULL,0,NULL,NULL,'Lịch nộp bài tập lớn môn Lập trình Web lớp D24-CNTT1 rơi vào ngày 30/4','Em thấy trên Canvas LMS hạn chốt nộp bài rơi đúng ngày 30/4 là ngày nghỉ lễ toàn quốc. Mong thầy cô hiệu chỉnh lại giúp lớp em.','Canvas LMS',NULL,'resolved',NULL,'2026-10-23 08:15:00','2026-10-23 08:15:00','2026-10-23 08:30:00','2026-10-23 10:00:00','2026-10-23 08:20:00','2026-10-29 09:41:30',NULL,0,'HD-2026-2910-P0T002',0,0,NULL,0,NULL,NULL,'pending',NULL,NULL,0,NULL,NULL,0,NULL,'none'),(3,14,2,1,3,NULL,1,NULL,NULL,1,'tranlinh.personal@gmail.com','4589','Tài khoản đăng nhập portal bị khóa cứng sau 5 lần nhập sai','Em bị khóa tài khoản do nhập sai 5 lần, đã xác minh thẻ sinh viên.','Portal SSO','uploads/attachments/the_sinh_vien_tran_thuc_linh.svg','closed','completed','2026-10-23 08:30:00','2026-10-23 08:30:00','2026-10-23 08:45:00','2026-10-23 10:30:00','2026-10-23 08:40:00','2026-10-29 09:38:02','2026-10-29 09:05:47',0,'HD-2026-2910-T0L003',0,0,NULL,0,NULL,NULL,'pending',NULL,NULL,0,NULL,NULL,0,NULL,'none'),(4,7,4,3,1,NULL,1,1,NULL,0,NULL,NULL,'[KHẨN CẤP] Cần mở quyền nhập điểm bổ sung học phần Lập trình Web Lớp D24-CNTT1','Cổng nhập điểm QLĐT đã quá hạn 12h, tôi đã có giấy phê duyệt của Phòng Đào tạo đề nghị mở khóa nhập điểm trong 24 giờ cho lớp D24-CNTT1.','QLĐT',NULL,'closed','','2026-10-22 14:00:00','2026-10-22 14:00:00','2026-10-22 14:15:00','2026-10-22 14:30:00','2026-10-22 14:05:00','2026-10-22 14:25